const raw = $input.first().json ?? {};
const telemetry = raw.data && typeof raw.data === 'object' ? raw.data : raw;
const reasons = [];
const now = Math.floor(Date.now() / 1000);
const createdEpoch = telemetry.createdEpoch;
const ageMinutes = Number.isSafeInteger(createdEpoch) ? Math.floor((now - createdEpoch) / 60) : null;
const completionFresh = ageMinutes !== null && ageMinutes >= 0 && ageMinutes <= 105;
if (!completionFresh) reasons.push('COMPLETION_STALE_OR_MISSING');
const integerFields = ['backupBytes', 'growth7Bytes', 'growth30Bytes', 'targetTotalBytes', 'targetFreeBytes', 'projectedFreePercent', 'projectedDaysToFull', 'restoreAgeDays'];
const integersValid = integerFields.every((key) => typeof telemetry[key] === 'number' && Number.isSafeInteger(telemetry[key]));
const rangesValid = integersValid && telemetry.backupBytes >= 0 && telemetry.targetTotalBytes > 0 && telemetry.targetFreeBytes >= 0 && telemetry.targetFreeBytes <= telemetry.targetTotalBytes && telemetry.projectedFreePercent >= 0 && telemetry.projectedFreePercent <= 100 && telemetry.projectedDaysToFull >= -1 && telemetry.restoreAgeDays >= -1;
const growthStatusesValid = ['available', 'insufficient_history'].includes(telemetry.growth7Status) && ['available', 'insufficient_history'].includes(telemetry.growth30Status);
if (telemetry.schemaVersion !== 'diis-backup-telemetry-v1' || !Number.isSafeInteger(createdEpoch) || !rangesValid || !growthStatusesValid) reasons.push('TELEMETRY_INVALID');
if (telemetry.projectedFreePercent < Number($env.BACKUP_MIN_FREE_PERCENT ?? 25)) reasons.push('CAPACITY_LOW');
if (telemetry.projectedDaysToFull >= 0 && telemetry.projectedDaysToFull < Number($env.BACKUP_MIN_DAYS_TO_FULL ?? 30)) reasons.push('DAYS_TO_FULL_LOW');
if (telemetry.offsiteStatus !== 'complete') reasons.push('OFFSITE_INCOMPLETE');
if (telemetry.restoreStatus !== 'success' || telemetry.restoreAgeDays < 0 || telemetry.restoreAgeDays > Number($env.BACKUP_MAX_RESTORE_AGE_DAYS ?? 35)) reasons.push('RESTORE_PROOF_MISSING_OR_STALE');
const notificationChannelStatus = ($env.FONNTE_API_KEY && $env.ADMIN_PHONE_NUMBER) ? 'configured' : 'disabled';
return [{ json: { completionFresh, ageMinutes, backupBytes: integersValid ? telemetry.backupBytes : 0, growth7Bytes: integersValid ? telemetry.growth7Bytes : 0, growth30Bytes: integersValid ? telemetry.growth30Bytes : 0, targetFreeBytes: integersValid ? telemetry.targetFreeBytes : 0, projectedFreePercent: integersValid ? telemetry.projectedFreePercent : 0, projectedDaysToFull: integersValid ? telemetry.projectedDaysToFull : -1, restoreStatus: String(telemetry.restoreStatus ?? 'missing'), restoreAgeDays: integersValid ? telemetry.restoreAgeDays : -1, notificationChannelStatus, reasonCodes: [...new Set(reasons)].sort(), alertRequired: reasons.length > 0 } }];
